window.GAOKAO_PAPERS=window.GAOKAO_PAPERS||{};window.GAOKAO_PAPERS["2025-shanghai"]=[{"id":"2025-shanghai-q01","paperId":"2025-shanghai","number":1,"type":"fill","score":4,"lessonIds":["1.3"],"difficulty":"基础","hint":"从[2,5]中拿掉[2,4)，注意4和5仍然留下。","legacy":false,"legacyReason":"","searchText":"已知全集 U = \\{x \\mid 2 \\le x \\le 5, x \\in \\R\\} ，集合 A = \\{x \\mid 2 \\le x < 4, x \\in \\R\\} ，则 \\bar{A} = ________ . ","questionHtml":"已知全集 <span class=\"gk-math\" data-tex=\"U = \\{x \\mid 2 \\le x \\le 5, x \\in \\R\\}\">U = \\{x \\mid 2 \\le x \\le 5, x \\in \\R\\}</span>，集合 <span class=\"gk-math\" data-tex=\"A = \\{x \\mid 2 \\le x &lt; 4, x \\in \\R\\}\">A = \\{x \\mid 2 \\le x &lt; 4, x \\in \\R\\}</span>，则 <span class=\"gk-math\" data-tex=\"\\bar{A} =\">\\bar{A} =</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\bar{A} = \\{x \\mid 4 \\le x \\le 5, x \\in \\R\\}=[4,5]\">\\bar{A} = \\{x \\mid 4 \\le x \\le 5, x \\in \\R\\}=[4,5]</span>","answerKey":"","solutionHtml":"根据补集定义，<span class=\"gk-math\" data-tex=\"\\bar{A} = \\{x \\mid x \\in U, x \\notin A\\}\">\\bar{A} = \\{x \\mid x \\in U, x \\notin A\\}</span>. 又 <span class=\"gk-math\" data-tex=\"U=\\{x\\mid2\\le x\\le5\\}\">U=\\{x\\mid2\\le x\\le5\\}</span>，所以 <span class=\"gk-math\" data-tex=\"\\bar{A}=\\{x\\mid4\\le x\\le5\\}\">\\bar{A}=\\{x\\mid4\\le x\\le5\\}</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q02","paperId":"2025-shanghai","number":2,"type":"fill","score":4,"lessonIds":["2.1","2.3"],"difficulty":"基础","hint":"分式为负说明分子与分母异号；先标出1和3两个分界点。","legacy":false,"legacyReason":"","searchText":"设 x\\in\\R ，不等式 \\frac{x-1}{x-3}<0 的解集为 ________ . ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"x\\in\\R\">x\\in\\R</span>，不等式 <span class=\"gk-math\" data-tex=\"\\frac{x-1}{x-3}&lt;0\">\\frac{x-1}{x-3}&lt;0</span> 的解集为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"(1,3)\">(1,3)</span>","answerKey":"","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"\\frac{x-1}{x-3}&lt;0\">\\frac{x-1}{x-3}&lt;0</span>，得 <span class=\"gk-math\" data-tex=\"1&lt;x&lt;3\">1&lt;x&lt;3</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q03","paperId":"2025-shanghai","number":3,"type":"fill","score":4,"lessonIds":["e2-4.2"],"difficulty":"基础","hint":"先算a₆，再用(首项+末项)×项数÷2。","legacy":false,"legacyReason":"","searchText":"已知等差数列 \\{a_n\\} 的首项 a_1 = -3 ，公差 d = 2 ，则该数列的前 6 项和为 ________ . ","questionHtml":"已知等差数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的首项 <span class=\"gk-math\" data-tex=\"a_1 = -3\">a_1 = -3</span>，公差 <span class=\"gk-math\" data-tex=\"d = 2\">d = 2</span>，则该数列的前 <span class=\"gk-math\" data-tex=\"6\">6</span> 项和为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"12\">12</span>","answerKey":"","solutionHtml":"由等差数列求和公式，<span class=\"gk-math\" data-tex=\"S_6 = \\frac{6(a_1+a_6)}{2}=3(a_1+a_6)\">S_6 = \\frac{6(a_1+a_6)}{2}=3(a_1+a_6)</span>，其中 <span class=\"gk-math\" data-tex=\"a_6=a_1+5d=7\">a_6=a_1+5d=7</span>，故 <span class=\"gk-math\" data-tex=\"S_6=3(-3+7)=12\">S_6=3(-3+7)=12</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q04","paperId":"2025-shanghai","number":4,"type":"fill","score":4,"lessonIds":["e3-6.3"],"difficulty":"基础","hint":"x³必须从5个因子里选3个2x，其余2个选−1。","legacy":false,"legacyReason":"","searchText":"在二项式 (2x-1)^5 的展开式中， x^3 的系数为 ________ . ","questionHtml":"在二项式 <span class=\"gk-math\" data-tex=\"(2x-1)^5\">(2x-1)^5</span> 的展开式中，<span class=\"gk-math\" data-tex=\"x^3\">x^3</span> 的系数为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"80\">80</span>","answerKey":"","solutionHtml":"二项式 <span class=\"gk-math\" data-tex=\"(2x-1)^5\">(2x-1)^5</span> 中 <span class=\"gk-math\" data-tex=\"x^3\">x^3</span> 的系数对应 <span class=\"gk-math\" data-tex=\"r=2\">r=2</span>，<span class=\"gk-math\" data-tex=\"\\mathrm{T}_{3}=\\mathrm C_5^2(2)^3(-1)^2=80\">\\mathrm{T}_{3}=\\mathrm C_5^2(2)^3(-1)^2=80</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q05","paperId":"2025-shanghai","number":5,"type":"fill","score":4,"lessonIds":["5.4"],"difficulty":"基础","hint":"在区间里标出x=0，再比较两端点和0处的余弦值。","legacy":false,"legacyReason":"","searchText":"函数 y=\\cos x 在 [-\\frac{\\pi}{2},\\frac{\\pi}{4}] 上的值域为 ________ . ","questionHtml":"函数 <span class=\"gk-math\" data-tex=\"y=\\cos x\">y=\\cos x</span> 在 <span class=\"gk-math\" data-tex=\"[-\\frac{\\pi}{2},\\frac{\\pi}{4}]\">[-\\frac{\\pi}{2},\\frac{\\pi}{4}]</span> 上的值域为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"[0,1]\">[0,1]</span>","answerKey":"","solutionHtml":"函数 <span class=\"gk-math\" data-tex=\"y=\\cos x\">y=\\cos x</span> 在 <span class=\"gk-math\" data-tex=\"[-\\frac{\\pi}{2},0]\">[-\\frac{\\pi}{2},0]</span> 上递增，在 <span class=\"gk-math\" data-tex=\"[0,\\frac{\\pi}{4}]\">[0,\\frac{\\pi}{4}]</span> 上递减. 并且 <span class=\"gk-math\" data-tex=\"y(-\\frac{\\pi}{2})=0\">y(-\\frac{\\pi}{2})=0</span>，<span class=\"gk-math\" data-tex=\"y(0)=1\">y(0)=1</span>，<span class=\"gk-math\" data-tex=\"y(\\frac{\\pi}{4})=\\frac{\\sqrt2}{2}\">y(\\frac{\\pi}{4})=\\frac{\\sqrt2}{2}</span>. 故值域为 <span class=\"gk-math\" data-tex=\"[0,1]\">[0,1]</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q06","paperId":"2025-shanghai","number":6,"type":"fill","score":4,"lessonIds":["e3-7.3"],"difficulty":"基础","hint":"期望就是每个取值乘自己的概率，再把它们加起来。","legacy":false,"legacyReason":"","searchText":"已知随机变量 X 的分布为 \\begin{pmatrix}5&6&7\\\\0.2&0.3&0.5\\end{pmatrix} ，则期望 E(X)= ________ . ","questionHtml":"已知随机变量 <span class=\"gk-math\" data-tex=\"X\">X</span> 的分布为 <span class=\"gk-math\" data-tex=\"\\begin{pmatrix}5&amp;6&amp;7\\\\0.2&amp;0.3&amp;0.5\\end{pmatrix}\">\\begin{pmatrix}5&amp;6&amp;7\\\\0.2&amp;0.3&amp;0.5\\end{pmatrix}</span>，则期望 <span class=\"gk-math\" data-tex=\"E(X)=\">E(X)=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"6.3\">6.3</span>","answerKey":"","solutionHtml":"由题意，<span class=\"gk-math\" data-tex=\"E(X)=5\\times0.2+6\\times0.3+7\\times0.5=1+1.8+3.5=6.3\">E(X)=5\\times0.2+6\\times0.3+7\\times0.5=1+1.8+3.5=6.3</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q07","paperId":"2025-shanghai","number":7,"type":"fill","score":5,"lessonIds":["8.3"],"difficulty":"进阶","hint":"底面正方形对角线给出边长，再用空间对角线求棱柱高。","legacy":false,"legacyReason":"","searchText":"如图，在正四棱柱 ABCD-A_1B_1C_1D_1 中， AC=4\\sqrt2 ， BD_1=9 ，则该正四棱柱的体积为 ________ . ","questionHtml":"如图，在正四棱柱 <span class=\"gk-math\" data-tex=\"ABCD-A_1B_1C_1D_1\">ABCD-A_1B_1C_1D_1</span> 中，<span class=\"gk-math\" data-tex=\"AC=4\\sqrt2\">AC=4\\sqrt2</span>，<span class=\"gk-math\" data-tex=\"BD_1=9\">BD_1=9</span>，则该正四棱柱的体积为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,350px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2025/shanghai/q7_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2025/shanghai/q7_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"334\" height=\"439\" style=\"aspect-ratio:334/439;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"112\">112</span>","answerKey":"","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"AC=4\\sqrt2\">AC=4\\sqrt2</span>，且 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 为正方形，所以 <span class=\"gk-math\" data-tex=\"BA=4\">BA=4</span>，从而 <span class=\"gk-math\" data-tex=\"BD=4\\sqrt2\">BD=4\\sqrt2</span>. 又 <span class=\"gk-math\" data-tex=\"BD_1=9\">BD_1=9</span>，所以 <span class=\"gk-math\" data-tex=\"BB_1^2+BD^2=9^2\">BB_1^2+BD^2=9^2</span>，得 <span class=\"gk-math\" data-tex=\"BB_1=7\">BB_1=7</span>. 底面积为 <span class=\"gk-math\" data-tex=\"BA\\cdot BC=16\">BA\\cdot BC=16</span>，体积 <span class=\"gk-math\" data-tex=\"=16\\times7=112\">=16\\times7=112</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q08","paperId":"2025-shanghai","number":8,"type":"fill","score":5,"lessonIds":["2.2"],"difficulty":"进阶","hint":"由条件把b换成1/(1−a)，将目标式合并成1/[a(1−a)]。","legacy":false,"legacyReason":"","searchText":"设 a ， b>0 ，若 a+\\frac1b=1 ，则 b+\\frac1a 的最小值为 ________ . ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"a\">a</span>，<span class=\"gk-math\" data-tex=\"b&gt;0\">b&gt;0</span>，若 <span class=\"gk-math\" data-tex=\"a+\\frac1b=1\">a+\\frac1b=1</span>，则 <span class=\"gk-math\" data-tex=\"b+\\frac1a\">b+\\frac1a</span> 的最小值为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"4\">4</span>","answerKey":"","solutionHtml":"由题设 <span class=\"gk-math\" data-tex=\"a+\\frac1b=1\">a+\\frac1b=1</span>，得 <span class=\"gk-math\" data-tex=\"0&lt;a&lt;1\">0&lt;a&lt;1</span>，且 <span class=\"gk-math\" data-tex=\"b=\\frac1{1-a}\">b=\\frac1{1-a}</span>. 因此 <span class=\"gk-math\" data-tex=\"b+\\frac1a=\\frac1{1-a}+\\frac1a=\\frac1{a(1-a)}\\ge4\">b+\\frac1a=\\frac1{1-a}+\\frac1a=\\frac1{a(1-a)}\\ge4</span>. 当 <span class=\"gk-math\" data-tex=\"a=\\frac12\">a=\\frac12</span>，<span class=\"gk-math\" data-tex=\"b=2\">b=2</span> 时取等号，故最小值为4.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q09","paperId":"2025-shanghai","number":9,"type":"fill","score":5,"lessonIds":["e3-6.2"],"difficulty":"进阶","hint":"先选首尾的两位家长并安排顺序，再排列中间4个人。","legacy":false,"legacyReason":"","searchText":"4 个家长和 2 个儿童去郊游爬山， 6 个人需要排成一条队列，要求队列的头和尾均是家长，则不同的排列个数有 ________ . ","questionHtml":"<span class=\"gk-math\" data-tex=\"4\">4</span> 个家长和 <span class=\"gk-math\" data-tex=\"2\">2</span> 个儿童去郊游爬山，<span class=\"gk-math\" data-tex=\"6\">6</span> 个人需要排成一条队列，要求队列的头和尾均是家长，则不同的排列个数有<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"288\">288</span>","answerKey":"","solutionHtml":"先安排首尾两位家长，有 <span class=\"gk-math\" data-tex=\"\\mathrm A_4^2=12\">\\mathrm A_4^2=12</span> 种；再安排中间 <span class=\"gk-math\" data-tex=\"4\">4</span> 人，有 <span class=\"gk-math\" data-tex=\"\\mathrm A_4^4=24\">\\mathrm A_4^4=24</span> 种，故共 <span class=\"gk-math\" data-tex=\"12\\times24=288\">12\\times24=288</span> 种.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q10","paperId":"2025-shanghai","number":10,"type":"fill","score":5,"lessonIds":["7.2","7.1"],"difficulty":"进阶","hint":"设z=x+yi，先由z²=共轭z的平方得到xy=0，再在复平面上找最近点。","legacy":false,"legacyReason":"","searchText":"i 为虚数单位，若复数 z 满足 z^2=(\\bar z)^2 ，且 |z|\\le1 ，则 |z-2-3\\i| 的最小值是 ________ . ","questionHtml":"<span class=\"gk-math\" data-tex=\"i\">i</span> 为虚数单位，若复数 <span class=\"gk-math\" data-tex=\"z\">z</span> 满足 <span class=\"gk-math\" data-tex=\"z^2=(\\bar z)^2\">z^2=(\\bar z)^2</span>，且 <span class=\"gk-math\" data-tex=\"|z|\\le1\">|z|\\le1</span>，则 <span class=\"gk-math\" data-tex=\"|z-2-3\\i|\">|z-2-3\\i|</span> 的最小值是<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"2\\sqrt2\">2\\sqrt2</span>","answerKey":"","solutionHtml":"设 <span class=\"gk-math\" data-tex=\"z=a+b\\i\">z=a+b\\i</span>（<span class=\"gk-math\" data-tex=\"a\">a</span>，<span class=\"gk-math\" data-tex=\"b\\in\\R\">b\\in\\R</span>），则 <span class=\"gk-math\" data-tex=\"\\bar z=a-b\\i\">\\bar z=a-b\\i</span>. 由 <span class=\"gk-math\" data-tex=\"z^2=a^2+2ab\\i-b^2\">z^2=a^2+2ab\\i-b^2</span>，<span class=\"gk-math\" data-tex=\"(\\bar z)^2=a^2-2ab\\i-b^2\">(\\bar z)^2=a^2-2ab\\i-b^2</span>， 可得 <span class=\"gk-math\" data-tex=\"4ab\\i=0\">4ab\\i=0</span>，所以 <span class=\"gk-math\" data-tex=\"ab=0\">ab=0</span>. 因此 <span class=\"gk-math\" data-tex=\"a=0\">a=0</span> 或 <span class=\"gk-math\" data-tex=\"b=0\">b=0</span>，即复数 <span class=\"gk-math\" data-tex=\"z\">z</span> 对应的点 <span class=\"gk-math\" data-tex=\"Z(a,b)\">Z(a,b)</span> 在线段 <span class=\"gk-math\" data-tex=\"[-1,1]\">[-1,1]</span> 的实轴部分或线段 <span class=\"gk-math\" data-tex=\"[-1,1]\">[-1,1]</span> 的虚轴部分上.<br><br>设 <span class=\"gk-math\" data-tex=\"E(2,3)\">E(2,3)</span>，则 <span class=\"gk-math\" data-tex=\"|z-2-3\\i|=|ZE|\">|z-2-3\\i|=|ZE|</span>.<br><br>当 <span class=\"gk-math\" data-tex=\"b=0\">b=0</span> 时，<span class=\"gk-math\" data-tex=\"|ZE|^2=(a-2)^2+9\">|ZE|^2=(a-2)^2+9</span>（<span class=\"gk-math\" data-tex=\"a\\in[-1,1]\">a\\in[-1,1]</span>）. 因为 <span class=\"gk-math\" data-tex=\"a\\le1\">a\\le1</span>，所以当 <span class=\"gk-math\" data-tex=\"a=1\">a=1</span> 时取最小值，此时 <span class=\"gk-math\" data-tex=\"|ZE|_{\\min}=\\sqrt{(1-2)^2+9}=\\sqrt{10}\">|ZE|_{\\min}=\\sqrt{(1-2)^2+9}=\\sqrt{10}</span>.<br><br>当 <span class=\"gk-math\" data-tex=\"a=0\">a=0</span> 时，<span class=\"gk-math\" data-tex=\"|ZE|^2=4+(b-3)^2\">|ZE|^2=4+(b-3)^2</span>（<span class=\"gk-math\" data-tex=\"b\\in[-1,1]\">b\\in[-1,1]</span>）. 因为 <span class=\"gk-math\" data-tex=\"b\\le1\">b\\le1</span>，所以当 <span class=\"gk-math\" data-tex=\"b=1\">b=1</span> 时取最小值，此时 <span class=\"gk-math\" data-tex=\"|ZE|_{\\min}=\\sqrt{4+(1-3)^2}=2\\sqrt2\">|ZE|_{\\min}=\\sqrt{4+(1-3)^2}=2\\sqrt2</span> 比较 <span class=\"gk-math\" data-tex=\"\\sqrt{10}\">\\sqrt{10}</span> 与 <span class=\"gk-math\" data-tex=\"2\\sqrt2\">2\\sqrt2</span>，得 <span class=\"gk-math\" data-tex=\"2\\sqrt2&lt;\\sqrt{10}\">2\\sqrt2&lt;\\sqrt{10}</span>. 故 <span class=\"gk-math\" data-tex=\"|z-2-3\\i|\">|z-2-3\\i|</span> 的最小值为 <span class=\"gk-math\" data-tex=\"2\\sqrt2\">2\\sqrt2</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q11","paperId":"2025-shanghai","number":11,"type":"fill","score":5,"lessonIds":["5.7","6.4"],"difficulty":"进阶","hint":"先用水平面上0.4米的影子确定阳光方向，再把斜面影长分成水平、竖直两段。","legacy":false,"legacyReason":"","searchText":"小申同学观察发现，生活中有时候影子可以完全投射在斜面上. 某斜面上有两根长为 1 米且垂直于水平面放置的杆子，与斜面的接触点分别为 A ， B ，它们在阳光的照射下呈现出影子，阳光可视为平行光，其中 A 处杆子的影子在水平面上，长度为 0.4 米， B 处杆子的影子完全在斜面上，长度为 0.45 米. 则斜面的坡角 \\theta= ________ （结果精确到 0.01^\\circ ）. ","questionHtml":"小申同学观察发现，生活中有时候影子可以完全投射在斜面上. 某斜面上有两根长为 <span class=\"gk-math\" data-tex=\"1\">1</span> 米且垂直于水平面放置的杆子，与斜面的接触点分别为 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span>，它们在阳光的照射下呈现出影子，阳光可视为平行光，其中 <span class=\"gk-math\" data-tex=\"A\">A</span> 处杆子的影子在水平面上，长度为 <span class=\"gk-math\" data-tex=\"0.4\">0.4</span> 米，<span class=\"gk-math\" data-tex=\"B\">B</span> 处杆子的影子完全在斜面上，长度为 <span class=\"gk-math\" data-tex=\"0.45\">0.45</span> 米. 则斜面的坡角 <span class=\"gk-math\" data-tex=\"\\theta=\">\\theta=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>（结果精确到 <span class=\"gk-math\" data-tex=\"0.01^\\circ\">0.01^\\circ</span>）.<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,699px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2025/shanghai/q11_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2025/shanghai/q11_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"683\" height=\"420\" style=\"aspect-ratio:683/420;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"12.58^\\circ\">12.58^\\circ</span>","answerKey":"","solutionHtml":"先由 <span class=\"gk-math\" data-tex=\"A\">A</span> 点杆子算出太阳光线与水平面的夹角 <span class=\"gk-math\" data-tex=\"x\">x</span>，有 <span class=\"gk-math\" data-tex=\"\\tan x=\\frac{1}{0.4}=2.5\">\\tan x=\\frac{1}{0.4}=2.5</span>. 在包含 <span class=\"gk-math\" data-tex=\"B\">B</span> 点杆子和阳光方向的竖直截面内，设 <span class=\"gk-math\" data-tex=\"C\">C</span> 为 <span class=\"gk-math\" data-tex=\"B\">B</span> 点杆顶，<span class=\"gk-math\" data-tex=\"E\">E</span> 为影子在斜面上的终点，过 <span class=\"gk-math\" data-tex=\"E\">E</span> 作水平线交 <span class=\"gk-math\" data-tex=\"B\">B</span> 点杆所在竖线于 <span class=\"gk-math\" data-tex=\"D\">D</span>. 设 <span class=\"gk-math\" data-tex=\"BD=y\">BD=y</span>，则 <span class=\"gk-math\" data-tex=\"CD=1+y\">CD=1+y</span>，且 <span class=\"gk-math\" data-tex=\"\\angle CED=x\">\\angle CED=x</span>，所以 <span class=\"gk-math\" data-tex=\"ED=\\frac{1+y}{2.5}\">ED=\\frac{1+y}{2.5}</span>. 由 <span class=\"gk-math\" data-tex=\"BE=0.45\">BE=0.45</span> 及勾股定理得 <span class=\"gk-math\" data-tex=\"y^2+\\left(\\frac{1+y}{2.5}\\right)^2=0.45^2\">y^2+\\left(\\frac{1+y}{2.5}\\right)^2=0.45^2</span> 解得 <span class=\"gk-math\" data-tex=\"y\\approx0.098\">y\\approx0.098</span>. 故 <span class=\"gk-math\" data-tex=\"\\theta=\\arcsin\\frac{y}{0.45}\\approx12.58^\\circ\">\\theta=\\arcsin\\frac{y}{0.45}\\approx12.58^\\circ</span>","sourceNote":"已对照独立PDF整理卷核对题干；解析中的计算与推导已复核。","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q12","paperId":"2025-shanghai","number":12,"type":"fill","score":5,"lessonIds":["6.3","5.4"],"difficulty":"挑战","hint":"三个符号相加为0，只能是一正一负一零；把垂直的两个单位向量设为坐标轴方向。","legacy":false,"legacyReason":"","searchText":"已知函数 f(x) 满足：当 x>0 时 f(x)=1 ，当 x=0 时 f(x)=0 ，当 x<0 时 f(x)=-1 . \\bs{a} ， \\bs{b} ， \\bs{c} 分别为平面内三个不同的单位向量. 若 f(\\bs{a}\\cdot\\bs{b})+f(\\bs{b}\\cdot\\bs{c})+f(\\bs{c}\\cdot\\bs{a})=0 ，则 |\\bs{a}+\\bs{b}+\\bs{c}| 的可取值范围是 ________ . ","questionHtml":"已知函数 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 满足：当 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span> 时 <span class=\"gk-math\" data-tex=\"f(x)=1\">f(x)=1</span>，当 <span class=\"gk-math\" data-tex=\"x=0\">x=0</span> 时 <span class=\"gk-math\" data-tex=\"f(x)=0\">f(x)=0</span>，当 <span class=\"gk-math\" data-tex=\"x&lt;0\">x&lt;0</span> 时 <span class=\"gk-math\" data-tex=\"f(x)=-1\">f(x)=-1</span>. <span class=\"gk-math\" data-tex=\"\\bs{a}\">\\bs{a}</span>，<span class=\"gk-math\" data-tex=\"\\bs{b}\">\\bs{b}</span>，<span class=\"gk-math\" data-tex=\"\\bs{c}\">\\bs{c}</span> 分别为平面内三个不同的单位向量. 若 <span class=\"gk-math\" data-tex=\"f(\\bs{a}\\cdot\\bs{b})+f(\\bs{b}\\cdot\\bs{c})+f(\\bs{c}\\cdot\\bs{a})=0\">f(\\bs{a}\\cdot\\bs{b})+f(\\bs{b}\\cdot\\bs{c})+f(\\bs{c}\\cdot\\bs{a})=0</span>，则 <span class=\"gk-math\" data-tex=\"|\\bs{a}+\\bs{b}+\\bs{c}|\">|\\bs{a}+\\bs{b}+\\bs{c}|</span> 的可取值范围是<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"(1,\\sqrt5)\">(1,\\sqrt5)</span>","answerKey":"","solutionHtml":"函数<span class=\"gk-math\" data-tex=\"f\">f</span>只记录数的正、零、负。三个结果相加为0，要么全为0，要么一正一负一零。三个平面单位向量不可能两两垂直，所以只能是一正一负一零。不妨设<span class=\"gk-math\" data-tex=\"\\bs b\\cdot\\bs c=0\">\\bs b\\cdot\\bs c=0</span>、<span class=\"gk-math\" data-tex=\"\\bs a\\cdot\\bs b&gt;0\">\\bs a\\cdot\\bs b&gt;0</span>、<span class=\"gk-math\" data-tex=\"\\bs a\\cdot\\bs c&lt;0\">\\bs a\\cdot\\bs c&lt;0</span>。取<span class=\"gk-math\" data-tex=\"\\bs b=(1,0)\">\\bs b=(1,0)</span>、<span class=\"gk-math\" data-tex=\"\\bs c=(0,1)\">\\bs c=(0,1)</span>，则<span class=\"gk-math\" data-tex=\"\\bs a=(\\cos\\theta,\\sin\\theta)\">\\bs a=(\\cos\\theta,\\sin\\theta)</span>，其中<span class=\"gk-math\" data-tex=\"3\\pi/2&lt;\\theta&lt;2\\pi\">3\\pi/2&lt;\\theta&lt;2\\pi</span>。 因此<div class=\"gk-math display\" data-tex=\"|\\bs a+\\bs b+\\bs c|^2=3+2(\\cos\\theta+\\sin\\theta).\">|\\bs a+\\bs b+\\bs c|^2=3+2(\\cos\\theta+\\sin\\theta).</div> 在该开区间内，<span class=\"gk-math\" data-tex=\"\\cos\\theta+\\sin\\theta\">\\cos\\theta+\\sin\\theta</span>严格递增，值域为<span class=\"gk-math\" data-tex=\"(-1,1)\">(-1,1)</span>，所以上式值域为<span class=\"gk-math\" data-tex=\"(1,5)\">(1,5)</span>。开平方得<span class=\"gk-math\" data-tex=\"|\\bs a+\\bs b+\\bs c|\\in(1,\\sqrt5)\">|\\bs a+\\bs b+\\bs c|\\in(1,\\sqrt5)</span>。","sourceNote":"已对照独立PDF整理卷核对题干；解析中的计算与推导已复核。","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q13","paperId":"2025-shanghai","number":13,"type":"single","score":4,"lessonIds":["10.2"],"difficulty":"基础","hint":"相互独立时，同时发生的概率就是两个概率相乘。","legacy":false,"legacyReason":"","searchText":"已知事件 A ， B 相互独立，若 P(A)=P(B)=\\frac{1}{2} ，则 P(A\\cap B) 的值为（ ） 0 \\frac{1}{4} \\frac{1}{2} 1","questionHtml":"已知事件 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span> 相互独立，若 <span class=\"gk-math\" data-tex=\"P(A)=P(B)=\\frac{1}{2}\">P(A)=P(B)=\\frac{1}{2}</span>，则 <span class=\"gk-math\" data-tex=\"P(A\\cap B)\">P(A\\cap B)</span> 的值为（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"0\">0</span>","<span class=\"gk-math\" data-tex=\"\\frac{1}{4}\">\\frac{1}{4}</span>","<span class=\"gk-math\" data-tex=\"\\frac{1}{2}\">\\frac{1}{2}</span>","<span class=\"gk-math\" data-tex=\"1\">1</span>"],"answerHtml":"B","answerKey":"B","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span> 相互独立，所以 <span class=\"gk-math\" data-tex=\"P(A\\cap B)=P(A)P(B)=\\frac{1}{2}\\times\\frac{1}{2}=\\frac{1}{4}\">P(A\\cap B)=P(A)P(B)=\\frac{1}{2}\\times\\frac{1}{2}=\\frac{1}{4}</span>. 故选 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q14","paperId":"2025-shanghai","number":14,"type":"single","score":4,"lessonIds":["4.2","1.4"],"difficulty":"进阶","hint":"把a写成a¹，再按a>1和0<a<1分开比较指数。","legacy":false,"legacyReason":"","searchText":"已知 a>0 且 a\\ne1 ， s\\in\\R ，下列各项中，能推出 a^s>a 的是（ ） a>1 且 s>0 a>1 且 s<0 0<a<1 且 s>0 0<a<1 且 s<0","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span> 且 <span class=\"gk-math\" data-tex=\"a\\ne1\">a\\ne1</span>，<span class=\"gk-math\" data-tex=\"s\\in\\R\">s\\in\\R</span>，下列各项中，能推出 <span class=\"gk-math\" data-tex=\"a^s&gt;a\">a^s&gt;a</span> 的是（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"a&gt;1\">a&gt;1</span> 且 <span class=\"gk-math\" data-tex=\"s&gt;0\">s&gt;0</span>","<span class=\"gk-math\" data-tex=\"a&gt;1\">a&gt;1</span> 且 <span class=\"gk-math\" data-tex=\"s&lt;0\">s&lt;0</span>","<span class=\"gk-math\" data-tex=\"0&lt;a&lt;1\">0&lt;a&lt;1</span> 且 <span class=\"gk-math\" data-tex=\"s&gt;0\">s&gt;0</span>","<span class=\"gk-math\" data-tex=\"0&lt;a&lt;1\">0&lt;a&lt;1</span> 且 <span class=\"gk-math\" data-tex=\"s&lt;0\">s&lt;0</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"把右边写成<span class=\"gk-math\" data-tex=\"a^1\">a^1</span>。当<span class=\"gk-math\" data-tex=\"a&gt;1\">a&gt;1</span>时，指数函数严格递增，<span class=\"gk-math\" data-tex=\"a^s&gt;a\">a^s&gt;a</span>等价于<span class=\"gk-math\" data-tex=\"s&gt;1\">s&gt;1</span>，A、B都不能保证；当<span class=\"gk-math\" data-tex=\"0&lt;a&lt;1\">0&lt;a&lt;1</span>时，指数函数严格递减，<span class=\"gk-math\" data-tex=\"a^s&gt;a\">a^s&gt;a</span>等价于<span class=\"gk-math\" data-tex=\"s&lt;1\">s&lt;1</span>。D中的<span class=\"gk-math\" data-tex=\"s&lt;0\">s&lt;0</span>能保证<span class=\"gk-math\" data-tex=\"s&lt;1\">s&lt;1</span>，而C中的<span class=\"gk-math\" data-tex=\"s&gt;0\">s&gt;0</span>不能保证。故选D。","sourceNote":"已对照独立PDF整理卷核对题干；解析中的计算与推导已复核。","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q15","paperId":"2025-shanghai","number":15,"type":"single","score":5,"lessonIds":["e1-3.2","e2-5.3"],"difficulty":"进阶","hint":"把C写成(√(y²+1),y)，三角形面积等于点C到直线AB的距离乘固定底边的一半。","legacy":false,"legacyReason":"","searchText":"已知 A(0,1) ， B(1,2) ， C 在 \\Gamma:x^2-y^2=1 （ x\\ge1 ， y\\ge0 ） 上，则 \\triangle ABC 的面积（ ） 有最大值，但没有最小值 没有最大值，但有最小值 既有最大值，也有最小值 既没有最大值，也没有最小值","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"A(0,1)\">A(0,1)</span>，<span class=\"gk-math\" data-tex=\"B(1,2)\">B(1,2)</span>，<span class=\"gk-math\" data-tex=\"C\">C</span> 在 <span class=\"gk-math\" data-tex=\"\\Gamma:x^2-y^2=1\">\\Gamma:x^2-y^2=1</span>（<span class=\"gk-math\" data-tex=\"x\\ge1\">x\\ge1</span>，<span class=\"gk-math\" data-tex=\"y\\ge0\">y\\ge0</span>） 上，则 <span class=\"gk-math\" data-tex=\"\\triangle ABC\">\\triangle ABC</span> 的面积（ ）","optionsHtml":["有最大值，但没有最小值","没有最大值，但有最小值","既有最大值，也有最小值","既没有最大值，也没有最小值"],"answerHtml":"A","answerKey":"A","solutionHtml":"直线<span class=\"gk-math\" data-tex=\"AB\">AB</span>的方程为<span class=\"gk-math\" data-tex=\"y=x+1\">y=x+1</span>，且<span class=\"gk-math\" data-tex=\"|AB|=\\sqrt2\">|AB|=\\sqrt2</span>。设<span class=\"gk-math\" data-tex=\"C=(\\sqrt{1+y^2},y)\">C=(\\sqrt{1+y^2},y)</span>，其中<span class=\"gk-math\" data-tex=\"y\\ge0\">y\\ge0</span>，则 <div class=\"gk-math display\" data-tex=\"S_{\\triangle ABC}=\\frac12\\bigl(\\sqrt{1+y^2}-y+1\\bigr).\">S_{\\triangle ABC}=\\frac12\\bigl(\\sqrt{1+y^2}-y+1\\bigr).</div> 因为<span class=\"gk-math\" data-tex=\"\\sqrt{1+y^2}-y=1/(\\sqrt{1+y^2}+y)\">\\sqrt{1+y^2}-y=1/(\\sqrt{1+y^2}+y)</span>，当<span class=\"gk-math\" data-tex=\"y\">y</span>从0增大时，这一项从1严格减小，并趋近0而取不到0。所以面积的值域为<span class=\"gk-math\" data-tex=\"(1/2,1]\">(1/2,1]</span>，有最大值1，没有最小值，选A。","sourceNote":"已对照独立PDF整理卷核对题干；解析中的计算与推导已复核。","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q16","paperId":"2025-shanghai","number":16,"type":"single","score":5,"lessonIds":["e2-4.1","2.1","e2-5.3"],"difficulty":"挑战","hint":"cₙ会在aₙ、bₙ之间移动；要对所有λ成立，就要较大的边小于较小边的2倍。","legacy":false,"legacyReason":"","searchText":"设 \\lambda\\in\\R ，数列 \\{a_n\\} ， \\{b_n\\} ， \\{c_n\\} 的通项分别为 a_n=10n-9 ， b_n=2^n ， c_n=\\lambda a_n+(1-\\lambda)b_n . 若对任意 \\lambda\\in[0,1] ， a_n ， b_n ， c_n 均能作为三角形的三边长，则满足条件的正整数 n 有（ ） 1个 3个 4个 无穷多个","questionHtml":"设 <span class=\"gk-math\" data-tex=\"\\lambda\\in\\R\">\\lambda\\in\\R</span>，数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span>，<span class=\"gk-math\" data-tex=\"\\{b_n\\}\">\\{b_n\\}</span>，<span class=\"gk-math\" data-tex=\"\\{c_n\\}\">\\{c_n\\}</span> 的通项分别为 <span class=\"gk-math\" data-tex=\"a_n=10n-9\">a_n=10n-9</span>，<span class=\"gk-math\" data-tex=\"b_n=2^n\">b_n=2^n</span>，<span class=\"gk-math\" data-tex=\"c_n=\\lambda a_n+(1-\\lambda)b_n\">c_n=\\lambda a_n+(1-\\lambda)b_n</span>. 若对任意 <span class=\"gk-math\" data-tex=\"\\lambda\\in[0,1]\">\\lambda\\in[0,1]</span>，<span class=\"gk-math\" data-tex=\"a_n\">a_n</span>，<span class=\"gk-math\" data-tex=\"b_n\">b_n</span>，<span class=\"gk-math\" data-tex=\"c_n\">c_n</span> 均能作为三角形的三边长，则满足条件的正整数 <span class=\"gk-math\" data-tex=\"n\">n</span> 有（ ）","optionsHtml":["1个","3个","4个","无穷多个"],"answerHtml":"B","answerKey":"B","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"c_n=\\lambda a_n+(1-\\lambda)b_n\">c_n=\\lambda a_n+(1-\\lambda)b_n</span>，<span class=\"gk-math\" data-tex=\"\\lambda\\in[0,1]\">\\lambda\\in[0,1]</span>， 可得 <span class=\"gk-math\" data-tex=\"\\min\\{a_n,b_n\\}\\le c_n\\le \\max\\{a_n,b_n\\}&lt;a_n+b_n\">\\min\\{a_n,b_n\\}\\le c_n\\le \\max\\{a_n,b_n\\}&lt;a_n+b_n</span>， 因此对任意 <span class=\"gk-math\" data-tex=\"\\lambda\\in[0,1]\">\\lambda\\in[0,1]</span>，都有 <span class=\"gk-math\" data-tex=\"c_n&lt;a_n+b_n\">c_n&lt;a_n+b_n</span>. 要使 <span class=\"gk-math\" data-tex=\"a_n\">a_n</span>，<span class=\"gk-math\" data-tex=\"b_n\">b_n</span>，<span class=\"gk-math\" data-tex=\"c_n\">c_n</span> 对任意 <span class=\"gk-math\" data-tex=\"\\lambda\\in[0,1]\">\\lambda\\in[0,1]</span> 都能构成三角形，只需再保证较大的那一边恒小于另外两边之和.<br><br>令 <span class=\"gk-math\" data-tex=\"f(x)=2^x-10x+9\">f(x)=2^x-10x+9</span>，则 <span class=\"gk-math\" data-tex=\"f&#x27;(x)=2^x\\ln2-10\">f&#x27;(x)=2^x\\ln2-10</span>. 因为 <span class=\"gk-math\" data-tex=\"f&#x27;(x)\">f&#x27;(x)</span> 单调递增，且 <span class=\"gk-math\" data-tex=\"f&#x27;(3)&lt;0\">f&#x27;(3)&lt;0</span>，<span class=\"gk-math\" data-tex=\"f&#x27;(4)&gt;0\">f&#x27;(4)&gt;0</span>， 所以存在 <span class=\"gk-math\" data-tex=\"x_0\\in(3,4)\">x_0\\in(3,4)</span>，使得 <span class=\"gk-math\" data-tex=\"f&#x27;(x_0)=0\">f&#x27;(x_0)=0</span>. 于是 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 先减后增，至多有两个零点. 又 <span class=\"gk-math\" data-tex=\"f(1)&gt;0\">f(1)&gt;0</span>，<span class=\"gk-math\" data-tex=\"f(2)&lt;0\">f(2)&lt;0</span>，<span class=\"gk-math\" data-tex=\"f(5)&lt;0\">f(5)&lt;0</span>，<span class=\"gk-math\" data-tex=\"f(6)&gt;0\">f(6)&gt;0</span>，所以 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 恰有两个零点，分别位于 <span class=\"gk-math\" data-tex=\"(1,2)\">(1,2)</span> 与 <span class=\"gk-math\" data-tex=\"(5,6)\">(5,6)</span> 内. 于是对正整数 <span class=\"gk-math\" data-tex=\"n\">n</span>，有 <span class=\"gk-math\" data-tex=\"10n-9\\le 2^n \\iff n=1 \\text{\\ 或\\ } n\\ge 6\">10n-9\\le 2^n \\iff n=1 \\text{\\ 或\\ } n\\ge 6</span> <span class=\"gk-math\" data-tex=\"10n-9\\ge 2^n \\iff n=2,3,4,5\">10n-9\\ge 2^n \\iff n=2,3,4,5</span><br><br>分两类讨论.<br><br>当 <span class=\"gk-math\" data-tex=\"a_n\\le b_n\">a_n\\le b_n</span> 时，即 <span class=\"gk-math\" data-tex=\"n=1\">n=1</span> 或 <span class=\"gk-math\" data-tex=\"n\\ge 6\">n\\ge 6</span>，有 <span class=\"gk-math\" data-tex=\"a_n\\le c_n\\le b_n\">a_n\\le c_n\\le b_n</span>. 此时要构成三角形，只需 <span class=\"gk-math\" data-tex=\"a_n+c_n&gt;b_n\">a_n+c_n&gt;b_n</span> 对任意 <span class=\"gk-math\" data-tex=\"c_n\">c_n</span> 成立. 因为 <span class=\"gk-math\" data-tex=\"c_n\">c_n</span> 的最小值为 <span class=\"gk-math\" data-tex=\"a_n\">a_n</span>，所以只需 <span class=\"gk-math\" data-tex=\"2a_n&gt;b_n\">2a_n&gt;b_n</span> 即 <span class=\"gk-math\" data-tex=\"2(10n-9)&gt;2^n\">2(10n-9)&gt;2^n</span>. 与 <span class=\"gk-math\" data-tex=\"a_n\\le b_n\">a_n\\le b_n</span> 合并，只有 <span class=\"gk-math\" data-tex=\"n=6\">n=6</span> 满足条件.<br><br>当 <span class=\"gk-math\" data-tex=\"a_n\\ge b_n\">a_n\\ge b_n</span> 时，即 <span class=\"gk-math\" data-tex=\"n=2\">n=2</span>，<span class=\"gk-math\" data-tex=\"3\">3</span>，<span class=\"gk-math\" data-tex=\"4\">4</span>，<span class=\"gk-math\" data-tex=\"5\">5</span>，有 <span class=\"gk-math\" data-tex=\"b_n\\le c_n\\le a_n\">b_n\\le c_n\\le a_n</span>. 此时要构成三角形，只需 <span class=\"gk-math\" data-tex=\"b_n+c_n&gt;a_n\">b_n+c_n&gt;a_n</span> 对任意 <span class=\"gk-math\" data-tex=\"c_n\">c_n</span> 成立. 因为 <span class=\"gk-math\" data-tex=\"c_n\">c_n</span> 的最小值为 <span class=\"gk-math\" data-tex=\"b_n\">b_n</span>，所以只需 <span class=\"gk-math\" data-tex=\"2b_n&gt;a_n\">2b_n&gt;a_n</span> 即 <span class=\"gk-math\" data-tex=\"2^{n+1}&gt;10n-9\">2^{n+1}&gt;10n-9</span>. 在 <span class=\"gk-math\" data-tex=\"n=2\">n=2</span>，<span class=\"gk-math\" data-tex=\"3\">3</span>，<span class=\"gk-math\" data-tex=\"4\">4</span>，<span class=\"gk-math\" data-tex=\"5\">5</span> 中，满足该不等式的只有 <span class=\"gk-math\" data-tex=\"n=4\">n=4</span>，<span class=\"gk-math\" data-tex=\"\\ 5\">\\ 5</span>.<br><br>综上，满足条件的正整数 <span class=\"gk-math\" data-tex=\"n\">n</span> 为 <span class=\"gk-math\" data-tex=\"4\">4</span>，<span class=\"gk-math\" data-tex=\"5\">5</span>，<span class=\"gk-math\" data-tex=\"6\">6</span>，共有 <span class=\"gk-math\" data-tex=\"3\">3</span> 个，故选 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q17","paperId":"2025-shanghai","number":17,"type":"written","score":14,"lessonIds":["9.2","e3-6.2","e3-8.2"],"difficulty":"进阶","hint":"中位数看第5、6项；回归直线一定经过(年份平均数,成绩平均数)。","legacy":false,"legacyReason":"","searchText":"2024 年巴黎奥运会，中国获得了男子 4\\times100 米混合泳接力金牌，以下是历届奥运会男子 4\\times100 米混合泳接力项目冠军成绩（单位：秒），数据按照升序排列. 206.78 207.46 207.95 209.34 209.35 210.68 213.73 214.84 216.93 216.93 求这组数据的极差与中位数； 从这 10 个数据中任选 3 个，求恰有 2 个数据大于 211 的概率； 若比赛成绩 y 关于年份 x 的回归方程为 y=-0.311x+\\hat b ，年份 x 的平均数为 2006 ，预测 2028 年男子 4\\times100 米混合泳接力项目冠军队的成绩（精确到 0.01 秒）. ","questionHtml":"2024 年巴黎奥运会，中国获得了男子 <span class=\"gk-math\" data-tex=\"4\\times100\">4\\times100</span> 米混合泳接力金牌，以下是历届奥运会男子 <span class=\"gk-math\" data-tex=\"4\\times100\">4\\times100</span> 米混合泳接力项目冠军成绩（单位：秒），数据按照升序排列.<br><br><div class=\"gk-center\"><div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td>206.78</td><td>207.46</td><td>207.95</td><td>209.34</td><td>209.35</td></tr><tr><td>210.68</td><td>213.73</td><td>214.84</td><td>216.93</td><td>216.93</td></tr></table></div></div><br><br><ol class=\"gk-subparts\"><li>求这组数据的极差与中位数；</li><li>从这 10 个数据中任选 3 个，求恰有 2 个数据大于 <span class=\"gk-math\" data-tex=\"211\">211</span> 的概率；</li><li>若比赛成绩 <span class=\"gk-math\" data-tex=\"y\">y</span> 关于年份 <span class=\"gk-math\" data-tex=\"x\">x</span> 的回归方程为 <span class=\"gk-math\" data-tex=\"y=-0.311x+\\hat b\">y=-0.311x+\\hat b</span>，年份 <span class=\"gk-math\" data-tex=\"x\">x</span> 的平均数为 <span class=\"gk-math\" data-tex=\"2006\">2006</span>，预测 <span class=\"gk-math\" data-tex=\"2028\">2028</span> 年男子 <span class=\"gk-math\" data-tex=\"4\\times100\">4\\times100</span> 米混合泳接力项目冠军队的成绩（精确到 <span class=\"gk-math\" data-tex=\"0.01\">0.01</span> 秒）.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>数据的最小值为 <span class=\"gk-math\" data-tex=\"206.78\">206.78</span>，最大值为 <span class=\"gk-math\" data-tex=\"216.93\">216.93</span>，故极差 <span class=\"gk-math\" data-tex=\"216.93-206.78=10.15\">216.93-206.78=10.15</span>；中间两数为 <span class=\"gk-math\" data-tex=\"209.35,210.68\">209.35,210.68</span>，中位数为 <span class=\"gk-math\" data-tex=\"\\frac{209.35+210.68}{2}=210.015\">\\frac{209.35+210.68}{2}=210.015</span>.</li><li>设恰有 2 个数据大于 <span class=\"gk-math\" data-tex=\"211\">211</span>，事件 <span class=\"gk-math\" data-tex=\"A\">A</span>. 则从 <span class=\"gk-math\" data-tex=\"4\">4</span> 个大于 <span class=\"gk-math\" data-tex=\"211\">211</span> 的数中选两个，且从剩下 <span class=\"gk-math\" data-tex=\"6\">6</span> 个中选一个： <span class=\"gk-math\" data-tex=\"P(A)=\\frac{\\mathrm C_4^2\\mathrm C_6^1}{\\mathrm C_{10}^3}=\\frac{36}{120}=\\frac3{10}\">P(A)=\\frac{\\mathrm C_4^2\\mathrm C_6^1}{\\mathrm C_{10}^3}=\\frac{36}{120}=\\frac3{10}</span>.</li><li>先求样本均值 <div class=\"gk-math display\" data-tex=\"\\begin{aligned}\n\\bar y\n&amp;=\\frac{206.78+207.46+207.95+209.34+209.35}{10}\\\\\n&amp;\\quad+\\frac{210.68+213.73+214.84+216.93+216.93}{10}=211.399.\n\\end{aligned}\">\\begin{aligned}\n\\bar y\n&amp;=\\frac{206.78+207.46+207.95+209.34+209.35}{10}\\\\\n&amp;\\quad+\\frac{210.68+213.73+214.84+216.93+216.93}{10}=211.399.\n\\end{aligned}</div> 由 <span class=\"gk-math\" data-tex=\"(\\bar x,\\bar y)=(2006,211.399)\">(\\bar x,\\bar y)=(2006,211.399)</span> 在回归线上，得 <span class=\"gk-math\" data-tex=\"\\hat b=835.265\">\\hat b=835.265</span>，故回归方程为 <span class=\"gk-math\" data-tex=\"y=-0.311x+835.265\">y=-0.311x+835.265</span> 代入 <span class=\"gk-math\" data-tex=\"x=2028\">x=2028</span>，得 <span class=\"gk-math\" data-tex=\"y=-0.311\\times2028+835.265 =204.557\\approx204.56\">y=-0.311\\times2028+835.265 =204.557\\approx204.56</span></li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q18","paperId":"2025-shanghai","number":18,"type":"written","score":14,"lessonIds":["8.3","8.5"],"difficulty":"进阶","hint":"第一问先由线面角求母线长；第二问找QO∥PB和OC∥BD这两组平行线。","legacy":false,"legacyReason":"","searchText":"如图， P 是圆锥顶点， O 为底面圆心， AB 为底面直径，且 AB=2 . 若直线 PA 与圆锥底面所成角为 \\frac{\\pi}{3} ，求圆锥侧面积； 已知 Q 是母线 PA 中点，点 C ， D 在底面圆周上，且弧 AC 长为 \\frac{\\pi}{3} ， CD\\parallel AB . 设点 T 在线段 OC 上，证明 QT\\parallel PBD 所在平面. ","questionHtml":"如图，<span class=\"gk-math\" data-tex=\"P\">P</span> 是圆锥顶点，<span class=\"gk-math\" data-tex=\"O\">O</span> 为底面圆心，<span class=\"gk-math\" data-tex=\"AB\">AB</span> 为底面直径，且 <span class=\"gk-math\" data-tex=\"AB=2\">AB=2</span>. <ol class=\"gk-subparts\"><li>若直线 <span class=\"gk-math\" data-tex=\"PA\">PA</span> 与圆锥底面所成角为 <span class=\"gk-math\" data-tex=\"\\frac{\\pi}{3}\">\\frac{\\pi}{3}</span>，求圆锥侧面积；</li><li>已知 <span class=\"gk-math\" data-tex=\"Q\">Q</span> 是母线 <span class=\"gk-math\" data-tex=\"PA\">PA</span> 中点，点 <span class=\"gk-math\" data-tex=\"C\">C</span>，<span class=\"gk-math\" data-tex=\"D\">D</span> 在底面圆周上，且弧 <span class=\"gk-math\" data-tex=\"AC\">AC</span> 长为 <span class=\"gk-math\" data-tex=\"\\frac{\\pi}{3}\">\\frac{\\pi}{3}</span>，<span class=\"gk-math\" data-tex=\"CD\\parallel AB\">CD\\parallel AB</span>. 设点 <span class=\"gk-math\" data-tex=\"T\">T</span> 在线段 <span class=\"gk-math\" data-tex=\"OC\">OC</span> 上，证明 <span class=\"gk-math\" data-tex=\"QT\\parallel PBD\">QT\\parallel PBD</span> 所在平面.</li></ol><br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,613px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2025/shanghai/q18_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2025/shanghai/q18_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"597\" height=\"540\" style=\"aspect-ratio:597/540;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>线面角为<span class=\"gk-math\" data-tex=\"\\angle PAO=\\pi/3\">\\angle PAO=\\pi/3</span>，底面半径<span class=\"gk-math\" data-tex=\"AO=1\">AO=1</span>，所以母线<span class=\"gk-math\" data-tex=\"PA=AO/\\cos(\\pi/3)=2\">PA=AO/\\cos(\\pi/3)=2</span>。圆锥侧面积<span class=\"gk-math\" data-tex=\"S=\\pi r l=2\\pi\">S=\\pi r l=2\\pi</span>。</li><li>由于<span class=\"gk-math\" data-tex=\"Q\">Q</span>、<span class=\"gk-math\" data-tex=\"O\">O</span>分别为<span class=\"gk-math\" data-tex=\"PA\">PA</span>、<span class=\"gk-math\" data-tex=\"AB\">AB</span>的中点，三角形中位线给出<span class=\"gk-math\" data-tex=\"QO\\parallel PB\">QO\\parallel PB</span>。又底面半径为1，弧<span class=\"gk-math\" data-tex=\"AC\">AC</span>长为<span class=\"gk-math\" data-tex=\"\\pi/3\">\\pi/3</span>，故<span class=\"gk-math\" data-tex=\"\\angle AOC=\\pi/3\">\\angle AOC=\\pi/3</span>。在底面中取<span class=\"gk-math\" data-tex=\"A=(-1,0)\">A=(-1,0)</span>、<span class=\"gk-math\" data-tex=\"B=(1,0)\">B=(1,0)</span>，不妨取<span class=\"gk-math\" data-tex=\"C=(-1/2,\\sqrt3/2)\">C=(-1/2,\\sqrt3/2)</span>。由<span class=\"gk-math\" data-tex=\"CD\\parallel AB\">CD\\parallel AB</span>得<span class=\"gk-math\" data-tex=\"D=(1/2,\\sqrt3/2)\">D=(1/2,\\sqrt3/2)</span>，于是<span class=\"gk-math\" data-tex=\"\\overrightarrow{BD}=(-1/2,\\sqrt3/2)=\\overrightarrow{OC}\">\\overrightarrow{BD}=(-1/2,\\sqrt3/2)=\\overrightarrow{OC}</span>，所以<span class=\"gk-math\" data-tex=\"OC\\parallel BD\">OC\\parallel BD</span>。两组相交直线分别平行，故平面<span class=\"gk-math\" data-tex=\"QOC\\parallel\">QOC\\parallel</span>平面<span class=\"gk-math\" data-tex=\"PBD\">PBD</span>。点<span class=\"gk-math\" data-tex=\"T\">T</span>在<span class=\"gk-math\" data-tex=\"OC\">OC</span>上，<span class=\"gk-math\" data-tex=\"QT\">QT</span>在平面<span class=\"gk-math\" data-tex=\"QOC\">QOC</span>内，所以<span class=\"gk-math\" data-tex=\"QT\\parallel\">QT\\parallel</span>平面<span class=\"gk-math\" data-tex=\"PBD\">PBD</span>。</li></ol>","sourceNote":"已对照独立PDF整理卷核对题干；解析中的计算与推导已复核。","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q19","paperId":"2025-shanghai","number":19,"type":"written","score":14,"lessonIds":["e2-5.3","4.4"],"difficulty":"进阶","hint":"先用f(1)=0求m；第二问把导数因式分解，看符号能否从正变负。","legacy":false,"legacyReason":"","searchText":"已知 f(x)=x^2-(m+2)x+m\\ln x ， m\\in\\R . 若 f(1)=0 ，求不等式 f(x)\\le x^2-1 的解集； 若 f(x) 在 (0,+\\infty) 上存在极大值，求 m 的取值范围. ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"f(x)=x^2-(m+2)x+m\\ln x\">f(x)=x^2-(m+2)x+m\\ln x</span>，<span class=\"gk-math\" data-tex=\"m\\in\\R\">m\\in\\R</span>. <ol class=\"gk-subparts\"><li>若 <span class=\"gk-math\" data-tex=\"f(1)=0\">f(1)=0</span>，求不等式 <span class=\"gk-math\" data-tex=\"f(x)\\le x^2-1\">f(x)\\le x^2-1</span> 的解集；</li><li>若 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 在 <span class=\"gk-math\" data-tex=\"(0,+\\infty)\">(0,+\\infty)</span> 上存在极大值，求 <span class=\"gk-math\" data-tex=\"m\">m</span> 的取值范围.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由 <span class=\"gk-math\" data-tex=\"f(1)=0\">f(1)=0</span> 得 <span class=\"gk-math\" data-tex=\"m=-1\">m=-1</span>，故 <span class=\"gk-math\" data-tex=\"f(x)=x^2-x-\\ln x\">f(x)=x^2-x-\\ln x</span>. 则 <span class=\"gk-math\" data-tex=\"f(x)\\le x^2-1\\iff x+\\ln x\\ge1\">f(x)\\le x^2-1\\iff x+\\ln x\\ge1</span> 设 <span class=\"gk-math\" data-tex=\"s(x)=x+\\ln x\">s(x)=x+\\ln x</span>，<span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>，<span class=\"gk-math\" data-tex=\"s&#x27;(x)=1+\\frac1x&gt;0\">s&#x27;(x)=1+\\frac1x&gt;0</span>，故 <span class=\"gk-math\" data-tex=\"s\">s</span> 在 <span class=\"gk-math\" data-tex=\"(0,+\\infty)\">(0,+\\infty)</span> 上增，且 <span class=\"gk-math\" data-tex=\"s(1)=1\">s(1)=1</span>，解集为 <span class=\"gk-math\" data-tex=\"[1,+\\infty)\">[1,+\\infty)</span>.</li><li>由 <div class=\"gk-math display\" data-tex=\"f&#x27;(x)=2x-m-2+\\frac{m}{x}=\\frac{2x^2-(m+2)x+m}{x}=\\frac{\\left(2x-m\\right)\\left(x-1\\right)}{x}\">f&#x27;(x)=2x-m-2+\\frac{m}{x}=\\frac{2x^2-(m+2)x+m}{x}=\\frac{\\left(2x-m\\right)\\left(x-1\\right)}{x}</div><br><br>当 <span class=\"gk-math\" data-tex=\"m\\le0\">m\\le0</span> 时，<span class=\"gk-math\" data-tex=\"\\frac{m}{2}\\le0\">\\frac{m}{2}\\le0</span>，在 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span> 上只有零点 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span>. 当 <span class=\"gk-math\" data-tex=\"x\\in(0,1)\">x\\in(0,1)</span> 时 <span class=\"gk-math\" data-tex=\"f&#x27;(x)&lt;0\">f&#x27;(x)&lt;0</span>，当 <span class=\"gk-math\" data-tex=\"x\\in(1,+\\infty)\">x\\in(1,+\\infty)</span> 时 <span class=\"gk-math\" data-tex=\"f&#x27;(x)&gt;0\">f&#x27;(x)&gt;0</span>，故 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span> 为极小值点，不符合题意.<br><br>当 <span class=\"gk-math\" data-tex=\"0&lt;m&lt;2\">0&lt;m&lt;2</span> 时，<span class=\"gk-math\" data-tex=\"0&lt;\\frac{m}{2}&lt;1\">0&lt;\\frac{m}{2}&lt;1</span>. 当 <span class=\"gk-math\" data-tex=\"x\\in\\left(0,\\frac{m}{2}\\right)\\cup(1,+\\infty)\">x\\in\\left(0,\\frac{m}{2}\\right)\\cup(1,+\\infty)</span> 时 <span class=\"gk-math\" data-tex=\"f&#x27;(x)&gt;0\">f&#x27;(x)&gt;0</span>，当 <span class=\"gk-math\" data-tex=\"x\\in\\left(\\frac{m}{2},1\\right)\">x\\in\\left(\\frac{m}{2},1\\right)</span> 时 <span class=\"gk-math\" data-tex=\"f&#x27;(x)&lt;0\">f&#x27;(x)&lt;0</span>，故 <span class=\"gk-math\" data-tex=\"x=\\frac{m}{2}\">x=\\frac{m}{2}</span> 为极大值点，符合题意.<br><br>当 <span class=\"gk-math\" data-tex=\"m=2\">m=2</span> 时，<span class=\"gk-math\" data-tex=\"f&#x27;(x)=\\frac{2\\left(x-1\\right)^2}{x}\\ge0\">f&#x27;(x)=\\frac{2\\left(x-1\\right)^2}{x}\\ge0</span>，故 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 无极大值点，不符合题意.<br><br>当 <span class=\"gk-math\" data-tex=\"m&gt;2\">m&gt;2</span> 时，<span class=\"gk-math\" data-tex=\"\\frac{m}{2}&gt;1\">\\frac{m}{2}&gt;1</span>. 当 <span class=\"gk-math\" data-tex=\"x\\in(0,1)\\cup\\left(\\frac{m}{2},+\\infty\\right)\">x\\in(0,1)\\cup\\left(\\frac{m}{2},+\\infty\\right)</span> 时 <span class=\"gk-math\" data-tex=\"f&#x27;(x)&gt;0\">f&#x27;(x)&gt;0</span>，当 <span class=\"gk-math\" data-tex=\"x\\in\\left(1,\\frac{m}{2}\\right)\">x\\in\\left(1,\\frac{m}{2}\\right)</span> 时 <span class=\"gk-math\" data-tex=\"f&#x27;(x)&lt;0\">f&#x27;(x)&lt;0</span>，故 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span> 为极大值点，符合题意.<br><br>综上，<span class=\"gk-math\" data-tex=\"m\">m</span> 的取值范围为 <span class=\"gk-math\" data-tex=\"m&gt;0\">m&gt;0</span> 且 <span class=\"gk-math\" data-tex=\"m\\ne2\">m\\ne2</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q20","paperId":"2025-shanghai","number":20,"type":"written","score":18,"lessonIds":["e1-3.1","6.3","e1-2.2"],"difficulty":"挑战","hint":"第二问先把向量等式翻译成P的坐标；第三问用中垂线斜率求m与a的关系。","legacy":false,"legacyReason":"","searchText":"已知椭圆 \\Gamma:\\frac{x^2}{a^2}+\\frac{y^2}{5}=1 （ a>\\sqrt5 ）， M(0,m) （ m>0 ）， A 为 \\Gamma 的右顶点. 若 \\Gamma 的焦点为 (2,0) ，求离心率 e ； 若 a=4 ，且 \\Gamma 上存在一点 P 满足 \\overrightarrow{PA}=2\\overrightarrow{MP} ，求 m ； 若线段 AM 的中垂线 l 的斜率为2， l 与 \\Gamma 交于 C ， D ，且 \\angle CMD 为钝角，求 a 的取值范围. ","questionHtml":"已知椭圆 <span class=\"gk-math\" data-tex=\"\\Gamma:\\frac{x^2}{a^2}+\\frac{y^2}{5}=1\">\\Gamma:\\frac{x^2}{a^2}+\\frac{y^2}{5}=1</span>（<span class=\"gk-math\" data-tex=\"a&gt;\\sqrt5\">a&gt;\\sqrt5</span>），<span class=\"gk-math\" data-tex=\"M(0,m)\">M(0,m)</span>（<span class=\"gk-math\" data-tex=\"m&gt;0\">m&gt;0</span>），<span class=\"gk-math\" data-tex=\"A\">A</span> 为 <span class=\"gk-math\" data-tex=\"\\Gamma\">\\Gamma</span> 的右顶点. <ol class=\"gk-subparts\"><li>若 <span class=\"gk-math\" data-tex=\"\\Gamma\">\\Gamma</span> 的焦点为 <span class=\"gk-math\" data-tex=\"(2,0)\">(2,0)</span>，求离心率 <span class=\"gk-math\" data-tex=\"e\">e</span>；</li><li>若 <span class=\"gk-math\" data-tex=\"a=4\">a=4</span>，且 <span class=\"gk-math\" data-tex=\"\\Gamma\">\\Gamma</span> 上存在一点 <span class=\"gk-math\" data-tex=\"P\">P</span> 满足 <span class=\"gk-math\" data-tex=\"\\overrightarrow{PA}=2\\overrightarrow{MP}\">\\overrightarrow{PA}=2\\overrightarrow{MP}</span>，求 <span class=\"gk-math\" data-tex=\"m\">m</span>；</li><li>若线段 <span class=\"gk-math\" data-tex=\"AM\">AM</span> 的中垂线 <span class=\"gk-math\" data-tex=\"l\">l</span> 的斜率为2， <span class=\"gk-math\" data-tex=\"l\">l</span> 与 <span class=\"gk-math\" data-tex=\"\\Gamma\">\\Gamma</span> 交于 <span class=\"gk-math\" data-tex=\"C\">C</span>，<span class=\"gk-math\" data-tex=\"D\">D</span>，且 <span class=\"gk-math\" data-tex=\"\\angle CMD\">\\angle CMD</span> 为钝角，求 <span class=\"gk-math\" data-tex=\"a\">a</span> 的取值范围.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由 <span class=\"gk-math\" data-tex=\"b^2=5\">b^2=5</span>，焦点 <span class=\"gk-math\" data-tex=\"(\\pm c,0)\">(\\pm c,0)</span> 有 <span class=\"gk-math\" data-tex=\"c=2\">c=2</span>，所以 <span class=\"gk-math\" data-tex=\"a=\\sqrt{c^2+b^2}=\\sqrt9=3\">a=\\sqrt{c^2+b^2}=\\sqrt9=3</span>，故 <span class=\"gk-math\" data-tex=\"e=\\frac{c}{a}=\\frac23\">e=\\frac{c}{a}=\\frac23</span>.</li><li>此时 <span class=\"gk-math\" data-tex=\"A(4,0)\">A(4,0)</span>，设 <span class=\"gk-math\" data-tex=\"P(x_P,y_P)\">P(x_P,y_P)</span>. 由 <span class=\"gk-math\" data-tex=\"\\overrightarrow{PA}=2\\overrightarrow{MP}\">\\overrightarrow{PA}=2\\overrightarrow{MP}</span> 得 <span class=\"gk-math\" data-tex=\"4-x_P=2x_P\">4-x_P=2x_P</span>，<span class=\"gk-math\" data-tex=\"-y_P=2(y_P-m)\">-y_P=2(y_P-m)</span>. 所以 <span class=\"gk-math\" data-tex=\"x_P=\\frac43\">x_P=\\frac43</span>，<span class=\"gk-math\" data-tex=\"y_P=\\frac{2m}{3}\">y_P=\\frac{2m}{3}</span>. 代入椭圆方程 <span class=\"gk-math\" data-tex=\"\\frac{x^2}{16}+\\frac{y^2}{5}=1\">\\frac{x^2}{16}+\\frac{y^2}{5}=1</span> 得 <span class=\"gk-math\" data-tex=\"\\frac{1}{9}+\\frac{4m^2}{45}=1\">\\frac{1}{9}+\\frac{4m^2}{45}=1</span>，故 <span class=\"gk-math\" data-tex=\"m=\\sqrt{10}\">m=\\sqrt{10}</span>.</li><li>由 <span class=\"gk-math\" data-tex=\"l\">l</span> 为 <span class=\"gk-math\" data-tex=\"AM\">AM</span> 的中垂线且斜率为 <span class=\"gk-math\" data-tex=\"2\">2</span>，知 <span class=\"gk-math\" data-tex=\"AM\">AM</span> 的斜率为 <span class=\"gk-math\" data-tex=\"-\\frac12\">-\\frac12</span>. 又 <span class=\"gk-math\" data-tex=\"k_{AM}=\\frac{m-0}{0-a}=-\\frac{m}{a}\">k_{AM}=\\frac{m-0}{0-a}=-\\frac{m}{a}</span>，故 <span class=\"gk-math\" data-tex=\"m=\\frac a2\">m=\\frac a2</span>. 于是 <span class=\"gk-math\" data-tex=\"AM\">AM</span> 的中点为 <span class=\"gk-math\" data-tex=\"\\left(\\frac a2,\\frac a4\\right)\">\\left(\\frac a2,\\frac a4\\right)</span>，直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 的方程为 <span class=\"gk-math\" data-tex=\"y-\\frac a4=2\\left(x-\\frac a2\\right)\">y-\\frac a4=2\\left(x-\\frac a2\\right)</span>，即 <span class=\"gk-math\" data-tex=\"y=2x-\\frac{3a}{4}\">y=2x-\\frac{3a}{4}</span>. 联立 <span class=\"gk-math\" data-tex=\"\\begin{cases}\n\\frac{x^2}{a^2}+\\frac{y^2}{5}=1,\\\\\ny=2x-\\frac{3a}{4},\n\\end{cases}\">\\begin{cases}\n\\frac{x^2}{a^2}+\\frac{y^2}{5}=1,\\\\\ny=2x-\\frac{3a}{4},\n\\end{cases}</span> 得 <span class=\"gk-math\" data-tex=\"(4a^2+5)x^2-3a^3x+\\frac{9a^4-80a^2}{16}=0\">(4a^2+5)x^2-3a^3x+\\frac{9a^4-80a^2}{16}=0</span>. 设两交点横坐标为 <span class=\"gk-math\" data-tex=\"x_1\">x_1</span>，<span class=\"gk-math\" data-tex=\"x_2\">x_2</span>，则由韦达定理可得 <span class=\"gk-math\" data-tex=\"x_1+x_2=\\frac{3a^3}{4a^2+5}\">x_1+x_2=\\frac{3a^3}{4a^2+5}</span>，<span class=\"gk-math\" data-tex=\"x_1x_2=\\frac{a^2(9a^2-80)}{16(4a^2+5)}\">x_1x_2=\\frac{a^2(9a^2-80)}{16(4a^2+5)}</span>. 又 <span class=\"gk-math\" data-tex=\"M\\left(0,\\frac a2\\right)\">M\\left(0,\\frac a2\\right)</span>，且 <span class=\"gk-math\" data-tex=\"y_i=2x_i-\\frac{3a}{4}\">y_i=2x_i-\\frac{3a}{4}</span>（<span class=\"gk-math\" data-tex=\"i=1\">i=1</span>，<span class=\"gk-math\" data-tex=\"2\">2</span>）. <span class=\"gk-math\" data-tex=\"\\angle CMD\">\\angle CMD</span> 为钝角当且仅当 <span class=\"gk-math\" data-tex=\"\\overrightarrow{MC}\\cdot\\overrightarrow{MD}&lt;0\">\\overrightarrow{MC}\\cdot\\overrightarrow{MD}&lt;0</span>，即 <span class=\"gk-math\" data-tex=\"x_1x_2+\\left(y_1-\\frac a2\\right)\\left(y_2-\\frac a2\\right)&lt;0\">x_1x_2+\\left(y_1-\\frac a2\\right)\\left(y_2-\\frac a2\\right)&lt;0</span>. 代入 <span class=\"gk-math\" data-tex=\"y_i=2x_i-\\frac{3a}{4}\">y_i=2x_i-\\frac{3a}{4}</span> 得 <span class=\"gk-math\" data-tex=\"5x_1x_2-\\frac{5a}{2}(x_1+x_2)+\\frac{25a^2}{16}&lt;0\">5x_1x_2-\\frac{5a}{2}(x_1+x_2)+\\frac{25a^2}{16}&lt;0</span> 再代入韦达定理，化简得 <span class=\"gk-math\" data-tex=\"\\frac{25a^2(a^2-11)}{16(4a^2+5)}&lt;0\">\\frac{25a^2(a^2-11)}{16(4a^2+5)}&lt;0</span> 因为 <span class=\"gk-math\" data-tex=\"a&gt;\\sqrt5\">a&gt;\\sqrt5</span>，所以 <span class=\"gk-math\" data-tex=\"16(4a^2+5)&gt;0\">16(4a^2+5)&gt;0</span>，从而 <span class=\"gk-math\" data-tex=\"a^2&lt;11\">a^2&lt;11</span>. 再结合 <span class=\"gk-math\" data-tex=\"a&gt;\\sqrt5\">a&gt;\\sqrt5</span>，得 <span class=\"gk-math\" data-tex=\"\\sqrt5&lt;a&lt;\\sqrt{11}\">\\sqrt5&lt;a&lt;\\sqrt{11}</span></li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2025-shanghai-q21","paperId":"2025-shanghai","number":21,"type":"written","score":18,"lessonIds":["3.1","3.2","1.3"],"difficulty":"挑战","hint":"Mₐ的意思是“向右走a后函数值没变”；最后一问先借偶性比较x与2−x。","legacy":false,"legacyReason":"","searchText":"已知函数 y=f(x) 定义域为 \\R . 对于正实数 a ，定义集合 M_a=\\{x\\mid f(x+a)=f(x)\\} . 若 f(x)=\\sin x ，判断 \\dfrac{\\pi}{3} 是否是 M_{\\pi} 的元素，请说明理由； 若 f(x)=x+2 （ x<0 ）， f(0)=0 ，且当 x>0 时 f(x)=\\sqrt{x} ， M_a\\neq\\varnothing ，求 a 的取值范围； 若 y=f(x) 是偶函数，当 x\\in(0,1] 时 f(x)=1-x ，且对任意 a\\in(0,2) ，有 M_a\\subset M_2 . 写出 f(x) 在 x\\in(1,2) 的解析式，并证明：对任意实数 c ，函数 f(x)-c 在 [-3,3] 上至多有9个零点. ","questionHtml":"已知函数 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 定义域为 <span class=\"gk-math\" data-tex=\"\\R\">\\R</span>. 对于正实数 <span class=\"gk-math\" data-tex=\"a\">a</span>，定义集合 <span class=\"gk-math\" data-tex=\"M_a=\\{x\\mid f(x+a)=f(x)\\}\">M_a=\\{x\\mid f(x+a)=f(x)\\}</span>. <ol class=\"gk-subparts\"><li>若 <span class=\"gk-math\" data-tex=\"f(x)=\\sin x\">f(x)=\\sin x</span>，判断 <span class=\"gk-math\" data-tex=\"\\dfrac{\\pi}{3}\">\\dfrac{\\pi}{3}</span> 是否是 <span class=\"gk-math\" data-tex=\"M_{\\pi}\">M_{\\pi}</span> 的元素，请说明理由；</li><li>若 <span class=\"gk-math\" data-tex=\"f(x)=x+2\">f(x)=x+2</span>（<span class=\"gk-math\" data-tex=\"x&lt;0\">x&lt;0</span>），<span class=\"gk-math\" data-tex=\"f(0)=0\">f(0)=0</span>，且当 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span> 时 <span class=\"gk-math\" data-tex=\"f(x)=\\sqrt{x}\">f(x)=\\sqrt{x}</span>，<span class=\"gk-math\" data-tex=\"M_a\\neq\\varnothing\">M_a\\neq\\varnothing</span>，求 <span class=\"gk-math\" data-tex=\"a\">a</span> 的取值范围；</li><li>若 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 是偶函数，当 <span class=\"gk-math\" data-tex=\"x\\in(0,1]\">x\\in(0,1]</span> 时 <span class=\"gk-math\" data-tex=\"f(x)=1-x\">f(x)=1-x</span>，且对任意 <span class=\"gk-math\" data-tex=\"a\\in(0,2)\">a\\in(0,2)</span>，有 <span class=\"gk-math\" data-tex=\"M_a\\subset M_2\">M_a\\subset M_2</span>. 写出 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 在 <span class=\"gk-math\" data-tex=\"x\\in(1,2)\">x\\in(1,2)</span> 的解析式，并证明：对任意实数 <span class=\"gk-math\" data-tex=\"c\">c</span>，函数 <span class=\"gk-math\" data-tex=\"f(x)-c\">f(x)-c</span> 在 <span class=\"gk-math\" data-tex=\"[-3,3]\">[-3,3]</span> 上至多有9个零点.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>计算得 <span class=\"gk-math\" data-tex=\"f\\left(\\frac{\\pi}{3}\\right)=\\sin\\frac{\\pi}{3}=\\frac{\\sqrt{3}}{2}\">f\\left(\\frac{\\pi}{3}\\right)=\\sin\\frac{\\pi}{3}=\\frac{\\sqrt{3}}{2}</span>，且 <span class=\"gk-math\" data-tex=\"f\\left(\\frac{\\pi}{3}+\\pi\\right)=-\\sin\\frac{\\pi}{3}=-\\frac{\\sqrt{3}}{2}\">f\\left(\\frac{\\pi}{3}+\\pi\\right)=-\\sin\\frac{\\pi}{3}=-\\frac{\\sqrt{3}}{2}</span>. 所以 <span class=\"gk-math\" data-tex=\"\\dfrac{\\pi}{3}\\notin M_{\\pi}\">\\dfrac{\\pi}{3}\\notin M_{\\pi}</span>.</li><li>取 <span class=\"gk-math\" data-tex=\"x_0\\in M_a\">x_0\\in M_a</span>，则 <span class=\"gk-math\" data-tex=\"f(x_0+a)=f(x_0)\">f(x_0+a)=f(x_0)</span> 且 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>.<br><br>若 <span class=\"gk-math\" data-tex=\"x_0&lt;0\">x_0&lt;0</span> 且 <span class=\"gk-math\" data-tex=\"x_0+a&lt;0\">x_0+a&lt;0</span>，则 <span class=\"gk-math\" data-tex=\"f(x_0+a)=x_0+a+2\\ne x_0+2=f(x_0)\">f(x_0+a)=x_0+a+2\\ne x_0+2=f(x_0)</span>，矛盾；若 <span class=\"gk-math\" data-tex=\"x_0\\ge0\">x_0\\ge0</span>，则 <span class=\"gk-math\" data-tex=\"x_0+a&gt;0\">x_0+a&gt;0</span>，从而 <span class=\"gk-math\" data-tex=\"f(x_0+a)=\\sqrt{x_0+a}\\ne\\sqrt{x_0}=f(x_0)\">f(x_0+a)=\\sqrt{x_0+a}\\ne\\sqrt{x_0}=f(x_0)</span>，也矛盾.<br><br>故必有 <span class=\"gk-math\" data-tex=\"x_0&lt;0\\le x_0+a\">x_0&lt;0\\le x_0+a</span>. 于是 <span class=\"gk-math\" data-tex=\"x_0+2=\\sqrt{x_0+a}\">x_0+2=\\sqrt{x_0+a}</span>.<br><br>因为 <span class=\"gk-math\" data-tex=\"-2\\le x_0&lt;0\">-2\\le x_0&lt;0</span>，所以 <span class=\"gk-math\" data-tex=\"a=(x_0+2)^2-x_0=\\left(x_0+\\frac{3}{2}\\right)^2+\\frac{7}{4}\\in\\left[\\frac{7}{4},4\\right)\">a=(x_0+2)^2-x_0=\\left(x_0+\\frac{3}{2}\\right)^2+\\frac{7}{4}\\in\\left[\\frac{7}{4},4\\right)</span>， 故 <span class=\"gk-math\" data-tex=\"a\\in\\left[\\frac{7}{4},4\\right)\">a\\in\\left[\\frac{7}{4},4\\right)</span>.</li><li>任取 <span class=\"gk-math\" data-tex=\"x_0\\in(1,2)\">x_0\\in(1,2)</span>，则 <span class=\"gk-math\" data-tex=\"x_0-2\\in(-1,0)\">x_0-2\\in(-1,0)</span>. 由于 <span class=\"gk-math\" data-tex=\"f\">f</span> 为偶函数，<span class=\"gk-math\" data-tex=\"f(x_0-2)=f(2-x_0)\">f(x_0-2)=f(2-x_0)</span>. 又 <span class=\"gk-math\" data-tex=\"(2-x_0)-(x_0-2)=4-2x_0\\in(0,2)\">(2-x_0)-(x_0-2)=4-2x_0\\in(0,2)</span>，所以 <span class=\"gk-math\" data-tex=\"x_0-2\\in M_{4-2x_0}\\subset M_2\">x_0-2\\in M_{4-2x_0}\\subset M_2</span>，从而 <div class=\"gk-math display\" data-tex=\"f(x_0)=f(x_0-2)=f(2-x_0)=1-(2-x_0)=x_0-1\">f(x_0)=f(x_0-2)=f(2-x_0)=1-(2-x_0)=x_0-1</div> 故当 <span class=\"gk-math\" data-tex=\"x\\in(1,2)\">x\\in(1,2)</span> 时，<span class=\"gk-math\" data-tex=\"f(x)=x-1\">f(x)=x-1</span>. 当 <span class=\"gk-math\" data-tex=\"s\\in(0,1)\">s\\in(0,1)</span> 时，<span class=\"gk-math\" data-tex=\"1-s\\in(0,1)\">1-s\\in(0,1)</span>，<span class=\"gk-math\" data-tex=\"1+s\\in(1,2)\">1+s\\in(1,2)</span>，于是 <span class=\"gk-math\" data-tex=\"f(1-s)=1-(1-s)=s\">f(1-s)=1-(1-s)=s</span>，<span class=\"gk-math\" data-tex=\"f(1+s)=(1+s)-1=s\">f(1+s)=(1+s)-1=s</span>. 故 <span class=\"gk-math\" data-tex=\"1-s\\in M_{2s}\\subset M_2\">1-s\\in M_{2s}\\subset M_2</span>，从而 <span class=\"gk-math\" data-tex=\"f(3-s)=f(1-s)=s\">f(3-s)=f(1-s)=s</span>. 由于 <span class=\"gk-math\" data-tex=\"3-s\\in(2,3)\">3-s\\in(2,3)</span>，所以当 <span class=\"gk-math\" data-tex=\"x\\in(2,3)\">x\\in(2,3)</span> 时，<span class=\"gk-math\" data-tex=\"f(x)=3-x\">f(x)=3-x</span>.<br><br>再由偶性可得 <span class=\"gk-math\" data-tex=\"f(x)=x+1\">f(x)=x+1</span>，<span class=\"gk-math\" data-tex=\"x\\in(-1,0)\">x\\in(-1,0)</span>，<span class=\"gk-math\" data-tex=\"f(x)=-x-1\">f(x)=-x-1</span>，<span class=\"gk-math\" data-tex=\"x\\in(-2,-1)\">x\\in(-2,-1)</span>，<span class=\"gk-math\" data-tex=\"f(x)=x+3\">f(x)=x+3</span>，<span class=\"gk-math\" data-tex=\"x\\in(-3,-2)\">x\\in(-3,-2)</span>.<br><br>设 <span class=\"gk-math\" data-tex=\"f(-3)=n\">f(-3)=n</span>. 若 <span class=\"gk-math\" data-tex=\"n\\in(0,1)\">n\\in(0,1)</span>，则 <span class=\"gk-math\" data-tex=\"-3+n\\in(-3,-2)\">-3+n\\in(-3,-2)</span>，从而 <span class=\"gk-math\" data-tex=\"f(-3+n)=(-3+n)+3=n=f(-3)\">f(-3+n)=(-3+n)+3=n=f(-3)</span>，故 <span class=\"gk-math\" data-tex=\"-3\\in M_n\\subset M_2\">-3\\in M_n\\subset M_2</span>，于是 <span class=\"gk-math\" data-tex=\"f(-1)=f(-3)=n\">f(-1)=f(-3)=n</span>. 但由偶性及 <span class=\"gk-math\" data-tex=\"f(1)=0\">f(1)=0</span>，得 <span class=\"gk-math\" data-tex=\"f(-1)=0\">f(-1)=0</span>，矛盾. 所以 <span class=\"gk-math\" data-tex=\"f(-3)\\notin(0,1)\">f(-3)\\notin(0,1)</span>. 再由偶性，得 <span class=\"gk-math\" data-tex=\"f(3)\\notin(0,1)\">f(3)\\notin(0,1)</span>.<br><br>令 <span class=\"gk-math\" data-tex=\"f(x)-c=0\">f(x)-c=0</span>，即 <span class=\"gk-math\" data-tex=\"f(x)=c\">f(x)=c</span>.<br><br>若 <span class=\"gk-math\" data-tex=\"c\\notin(0,1)\">c\\notin(0,1)</span>，则六个开区间 <span class=\"gk-math\" data-tex=\"(-3,-2)\">(-3,-2)</span>，<span class=\"gk-math\" data-tex=\"(-2,-1)\">(-2,-1)</span>，<span class=\"gk-math\" data-tex=\"(-1,0)\">(-1,0)</span>，<span class=\"gk-math\" data-tex=\"(0,1)\">(0,1)</span>，<span class=\"gk-math\" data-tex=\"(1,2)\">(1,2)</span>，<span class=\"gk-math\" data-tex=\"(2,3)\">(2,3)</span> 内均无零点，此时零点只可能出现在 <span class=\"gk-math\" data-tex=\"-3\">-3</span>，<span class=\"gk-math\" data-tex=\"-2\">-2</span>，<span class=\"gk-math\" data-tex=\"0\">0</span>，<span class=\"gk-math\" data-tex=\"2\">2</span>，<span class=\"gk-math\" data-tex=\"3\">3</span> 这 5 个点上；特别地，当 <span class=\"gk-math\" data-tex=\"c=0\">c=0</span> 时，又有 <span class=\"gk-math\" data-tex=\"x=\\pm1\">x=\\pm1</span> 两个零点，所以此时零点至多有 7 个.<br><br>若 <span class=\"gk-math\" data-tex=\"0&lt;c&lt;1\">0&lt;c&lt;1</span>，则上述 6 个开区间内各至多有 1 个零点；又 <span class=\"gk-math\" data-tex=\"f(\\pm3)\\notin(0,1)\">f(\\pm3)\\notin(0,1)</span>，所以只可能在 <span class=\"gk-math\" data-tex=\"-2\">-2</span>，<span class=\"gk-math\" data-tex=\"0\">0</span>，<span class=\"gk-math\" data-tex=\"2\">2</span> 这 3 个点处再出现零点，从而零点总数不超过 <span class=\"gk-math\" data-tex=\"6+3=9\">6+3=9</span>.<br><br>综上，函数 <span class=\"gk-math\" data-tex=\"f(x)-c\">f(x)-c</span> 在 <span class=\"gk-math\" data-tex=\"[-3,3]\">[-3,3]</span> 上至多有 9 个零点.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]}];
